files.billing.py:
def invoice_total(lines):
    return round(sum(lines), 2)


def receipt_label(number):
    return f"INV-{number}"

files.transport.py:
def retry_delay(attempt):
    return min(2 ** attempt, 60)


def request_id(value):
    return str(value)

